        var eps = r.pick([0.1, 0.3, 0.5, 0.8, 0.9, 0.95]), t1 = r.int(5, 60) * 10, t2 = r.int(0, 30), T1 = t1 + 273.15, T2 = t2 + 273.15, qr = eps * sig * Ap * (Math.pow(T1, 4) - Math.pow(T2, 4));
