        return Q(data + t("Berechne die Stichproben-Standardabweichung s (auf 0,001).", "Compute the sample standard deviation s (to 0.001)."), num(sd, 3, "", 0.0011), t("Erst die Varianz mit n − 1, dann die Wurzel.", "First the variance with n − 1, then the square root."), ["x̄ = " + n(mean, 3), "s<sup>2</sup> = " + n(s2, 4), "s = " + n(sd, 3)], M.near(alt, sd * sd, 1e-9));
