        var perH = r.int(2, 30), mins = r.pick([5, 10, 12, 15, 20, 30]), l2 = perH * mins / 60, kk = r.int(0, 3), cum = 0; for (var j = 0; j <= kk; j += 1) cum += pois(l2, j);
