        var ctx = t("Die Länge gefertigter Bolzen ist normalverteilt mit μ = " + mu + " mm und σ = " + sg + " mm. ", "The length of manufactured bolts is normally distributed with μ = " + mu + " mm and σ = " + sg + " mm. ");
