        var p = r.pick([0.1, 0.25, 0.5, 0.75, 0.9, 0.95]), q = -Math.log(1 - p) * mean;
        return Q(t("Bauteile fallen exponentialverteilt mit mittlerer Lebensdauer " + mean + " h aus. Nach welcher Zeit sind " + n(p * 100) + " % der Teile ausgefallen (auf 0,01 h)?", "Components fail exponentially with a mean life of " + mean + " h. After what time have " + n(p * 100) + "% of the parts failed (to 0.01 h)?"),
            num(q, 2, "h", 0.006), t("Löse 1 − e<sup>−t/" + mean + "</sup> = " + n(p) + " nach t auf.", "Solve 1 − e<sup>−t/" + mean + "</sup> = " + n(p) + " for t."), ["e<sup>−t/" + mean + "</sup> = " + n(1 - p), "t = −" + mean + " · ln(" + n(1 - p) + ") = " + n(q, 2) + " h"], M.near(1 - Math.exp(-q / mean), p, 1e-9));
