    E.add({ id: "k-st-bayes", topic: "K-ST-6", title: t("Satz von Bayes", "Bayes' theorem"), gen: function (r, d) {
        var prev = r.pick([0.001, 0.002, 0.005, 0.01, 0.02, 0.05, 0.1]), se = r.pick([0.9, 0.95, 0.98, 0.99]), sp = r.pick([0.9, 0.95, 0.97, 0.98, 0.99]);
        var N = 1e6, sick = N * prev, tp = sick * se, fp = (N - sick) * (1 - sp), fn = sick - tp, tn = (N - sick) - fp;
        var ctx = t("Eine Krankheit hat eine Häufigkeit von " + n(prev * 100) + " %. Ein Test erkennt Kranke mit " + n(se * 100) + " % (Sensitivität) und Gesunde mit " + n(sp * 100) + " % (Spezifität). ", "A disease has a prevalence of " + n(prev * 100) + "%. A test detects the sick with " + n(se * 100) + "% (sensitivity) and the healthy with " + n(sp * 100) + "% (specificity). ");
        var pPos = se * prev + (1 - sp) * (1 - prev), ppv = se * prev / pPos;
        if (d === 1) return Q(ctx + t("Wie wahrscheinlich ist jemand mit positivem Test wirklich krank (in %, auf 0,01 %)?", "How likely is someone with a positive test actually sick (in %, to 0.01%)?"), num(ppv * 100, 2, "%", 0.006), t("Bayes: P(K | +) = P(+ | K) · P(K) / P(+). Stell dir eine Million Menschen vor.", "Bayes: P(S | +) = P(+ | S) · P(S) / P(+). Imagine a million people."), [t("Von 1.000.000: krank ", "Of 1,000,000: sick ") + n(sick, 0) + t(", davon positiv ", ", of whom positive ") + n(tp, 0), t("gesund, aber positiv: ", "healthy but positive: ") + n(fp, 0), "P(K | +) = " + n(tp, 0) + " / (" + n(tp, 0) + " + " + n(fp, 0) + ") = " + n(ppv * 100, 2) + " %"], M.near(tp / (tp + fp), ppv, 1e-9));
        if (d === 2) return Q(ctx + t("Wie groß ist der Anteil aller Getesteten mit positivem Ergebnis (in %, auf 0,001 %)?", "What share of everyone tested gets a positive result (in %, to 0.001%)?"), num(pPos * 100, 3, "%", 0.0006), t("Satz der totalen Wahrscheinlichkeit: richtig positive plus falsch positive.", "Law of total probability: true positives plus false positives."), ["P(+) = " + n(se) + " · " + n(prev) + " + " + n(1 - sp, 2) + " · " + n(1 - prev, 3) + " = " + n(pPos * 100, 3) + " %"], M.near((tp + fp) / N, pPos, 1e-9));
        var p2 = se * ppv / (se * ppv + (1 - sp) * (1 - ppv)), tp2 = tp * se, fp2 = fp * (1 - sp);
        return Q(ctx + t("Nach einem positiven Test wird unabhängig ein zweites Mal getestet, wieder positiv. Wie wahrscheinlich ist die Person jetzt krank (in %, auf 0,01 %)?", "After a positive test, an independent second test is done and is positive again. How likely is the person sick now (in %, to 0.01%)?"),
            num(p2 * 100, 2, "%", 0.006), t("Das Ergebnis des ersten Tests ist die neue Vorab-Wahrscheinlichkeit für den zweiten.", "The result of the first test becomes the new prior for the second."), [t("nach Test 1: ", "after test 1: ") + n(ppv * 100, 3) + " %", "P = " + n(se) + " · " + n(ppv, 5) + " / (" + n(se) + " · " + n(ppv, 5) + " + " + n(1 - sp, 2) + " · " + n(1 - ppv, 5) + ") = " + n(p2 * 100, 2) + " %"], M.near(tp2 / (tp2 + fp2), p2, 1e-9) && fn >= 0 && tn >= 0);
    } });
